package("simdutf")
    set_homepage("https://simdutf.github.io/simdutf")
    set_license("MIT")
    set_urls("$(projectdir)/third_party/sources/simdutf-$(version).tar.gz")
    add_versions("8.2.0", "033a91b1d7d1cb818c1eff49e61faaa1b64a3a530d59ef9efef0195e56bda8b1")
    add_deps("cmake")
    on_install(function (package)
        import("package.tools.cmake").install(package, {"-DSIMDUTF_TESTS=OFF", "-DSIMDUTF_TOOLS=OFF", "-DBUILD_SHARED_LIBS=OFF"})
    end)
